    public PojoTypeInfo(Class<T> typeClass, List<PojoField> fields) {
        super(typeClass);

        checkArgument(
                Modifier.isPublic(typeClass.getModifiers()), "POJO %s is not public", typeClass);

        this.fields = fields.toArray(new PojoField[fields.size()]);

