/**
     * Creates a new bulk copy helper.
     *
     * @param asyncClient the S3 async client used for downloads
     * @param maxConcurrentCopies the requested maximum number of concurrent copy operations
     * @param maxConnections the HTTP connection pool size; if {@code maxConcurrentCopies} exceeds
     *     this value, it is clamped down to prevent connection pool exhaustion
     * @param downloadBufferSize the buffer size in bytes used to write each downloaded file to the
     *     local filesystem; bounds the temporary direct buffers the JDK caches for channel writes
     */
NativeS3BulkCopyHelper(
            S3AsyncClient asyncClient,
            int maxConcurrentCopies,
            int maxConnections,
            int downloadBufferSize) {
        checkArgument(maxConcurrentCopies > 0, "maxConcurrentCopies must be positive");
        checkArgument(maxConnections > 0, "maxConnections must be positive");
        checkArgument(downloadBufferSize > 0, "downloadBufferSize must be positive");
        this.asyncClient = asyncClient;
        this.maxConnections = maxConnections;
        this.downloadBufferSize = downloadBufferSize;
        if (maxConcurrentCopies > maxConnections) {
            LOG.warn(
                    "{} ({}) exceeds {} ({}). "
                            + "Clamping concurrent copies to {} to prevent connection pool exhaustion.",
                    NativeS3FileSystemFactory.BULK_COPY_MAX_CONCURRENT.key(),
                    maxConcurrentCopies,
                    NativeS3FileSystemFactory.MAX_CONNECTIONS.key(),
                    maxConnections,
                    maxConnections);
            this.maxConcurrentCopies = maxConnections;
        } else {
            this.maxConcurrentCopies = maxConcurrentCopies;
        }
    }

public NativeS3FileSystem(
            S3ClientProvider clientProvider,
            URI uri,
            @Nullable String entropyInjectionKey,
            int entropyLength,
            String localTmpDir,
            long s3uploadPartSize,
            int maxConcurrentUploadsPerStream,
            @Nullable NativeS3BulkCopyHelper bulkCopyHelper,
            boolean useAsyncOperations,
            int readBufferSize,
            Duration fsCloseTimeout,
            boolean deleteBatchEnabled) {
        this.clientProvider =
                Preconditions.checkNotNull(clientProvider, "clientProvider must not be null");
        this.uri = uri;
        this.bucketName = uri.getHost();
        this.entropyInjectionKey = entropyInjectionKey;
        this.entropyLength = entropyLength;
        this.localTmpDir = localTmpDir;
        this.s3uploadPartSize = s3uploadPartSize;
        this.maxConcurrentUploadsPerStream = maxConcurrentUploadsPerStream;
        this.useAsyncOperations = useAsyncOperations;
        this.readBufferSize = readBufferSize;
        this.fsCloseTimeout = fsCloseTimeout;
        this.deleteBatchEnabled = deleteBatchEnabled;
        this.s3AccessHelper =
                new NativeS3ObjectOperations(
                        clientProvider.getS3Client(),
                        clientProvider.getTransferManager(),
                        bucketName,
                        useAsyncOperations,
                        clientProvider.getEncryptionConfig());
        this.bulkCopyHelper = bulkCopyHelper;

        if (entropyInjectionKey != null && entropyLength <= 0) {
            throw new IllegalArgumentException(
                    "Entropy length must be >= 0 when entropy injection key is set");
        }

        LOG.info(
                "Created Native S3 FileSystem for bucket: {}, entropy injection: {}, bulk copy: {}, read buffer: {} KB, delete batching: {}",
                bucketName,
                entropyInjectionKey != null,
                bulkCopyHelper != null,
                readBufferSize / 1024,
                deleteBatchEnabled);
    }

/**
     * Returns the stable SDK metric publisher shared by all clients, or {@code null} when metrics
     * are disabled. The publisher must be installed even before a metric group is available because
     * runtime startup may cache a file system before attaching metrics.
     */
@Nullable
    private synchronized AwsSdkMetricBridge resolveMetricBridge(Configuration config) {
        if (!config.get(METRICS_ENABLED)) {
            return null;
        }
        if (metricBridge == null) {
            metricBridge =
                    new AwsSdkMetricBridge(
                            config.get(METRICS_ALLOWLIST),
                            config.get(METRICS_HISTOGRAM_WINDOW_SIZE));
            if (pluginMetrics != null) {
                metricBridge.setMetricGroup(pluginMetrics);
            }
        }
        return metricBridge;
    }

