private static GenericArrayData iterableToArrayData(
            Iterable<?> iterable, LogicalType elementType) {
        return new GenericArrayData(
                StreamSupport.stream(iterable.spliterator(), false)
                        .map(v -> toInternal(v, elementType))
                        .toArray());
    }

private static GenericArrayData objectArrayToArrayData(Object[] src, LogicalType elementType) {
        Object[] arr = new Object[src.length];
        for (int i = 0; i < src.length; i++) {
            arr[i] = toInternal(src[i], elementType);
        }
        return new GenericArrayData(arr);
    }

private static GenericMapData mapEntryIterableToMapData(
            Iterable<?> iterable, LogicalType keyType, LogicalType valueType) {
        LinkedHashMap<Object, Object> converted = new LinkedHashMap<>();
        for (Object element : iterable) {
            if (!(element instanceof Map.Entry)) {
                throw new UnsupportedOperationException(
                        "Map conversion supports only Iterable<Map.Entry> but received: "
                                + iterable.getClass().getName());
            }
            Map.Entry<?, ?> entry = (Map.Entry<?, ?>) element;
            converted.put(
                    toInternal(entry.getKey(), keyType), toInternal(entry.getValue(), valueType));
        }
        return new GenericMapData(converted);
    }

private static GenericMapData mapToMapData(
            Map<?, ?> map, LogicalType keyType, LogicalType valueType) {
        LinkedHashMap<Object, Object> converted = new LinkedHashMap<>(map.size());
        for (Map.Entry<?, ?> entry : map.entrySet()) {
            converted.put(
                    toInternal(entry.getKey(), keyType), toInternal(entry.getValue(), valueType));
        }
        return new GenericMapData(converted);
    }

private static GenericRowData rowToGenericRowData(Row row, RowType rowType) {
        List<RowType.RowField> fields = rowType.getFields();
        GenericRowData out = new GenericRowData(row.getArity());
        out.setRowKind(row.getKind());
        for (int i = 0; i < row.getArity(); i++) {
            LogicalType fieldType = i < fields.size() ? fields.get(i).getType() : null;
            Object rawField = row.getField(i);
            out.setField(i, fieldType != null ? toInternal(rawField, fieldType) : rawField);
        }
        return out;
    }

private GenericRowData readFields(DataInputView source) throws IOException {
        GenericRowData row = new GenericRowData(numFields);
        for (int i = 0; i < numFields; i++) {
            boolean isNull = source.readBoolean();
            if (isNull) {
                row.setField(i, null);
                continue;
            }
            // Unlike the conversion step below, a deserialize() failure here means the stream
            // position for this and every subsequent field/row is now unknown: continuing to read
            // would silently cascade garbage into later rows. Fail loudly instead, mirroring
            // PojoSerializer.deserialize(), which never catches per-field failures either.
            Object raw = fieldDeserializers[i].deserialize(source);
            try {
                row.setField(i, InternalTypeConverter.toInternal(raw, fieldTypes[i]));
            } catch (Exception e) {
                // Bytes were already consumed correctly, so the stream is still aligned for
                // subsequent fields/rows; only this field's value could not be mapped to its
                // table-internal representation. Safe to null just this field and continue.
                LOG.warn(
                        "Failed to convert field '{}' (index {}) value: {}. Setting field to null.",
                        fieldNames[i],
                        i,
                        e.getMessage());
                row.setField(i, null);
            }
        }
        return row;
    }

Object getValue(LogicalType logicalType, Object object) {
        if (object == null) {
            return null;
        }
        switch (logicalType.getTypeRoot()) {
            case ROW:
                if (object instanceof TimeWindow) {
                    TimeWindow window = (TimeWindow) object;
                    GenericRowData result = new GenericRowData(RowKind.INSERT, 2);
                    result.setField(0, TimestampData.fromEpochMillis(window.getStart()));
                    result.setField(1, TimestampData.fromEpochMillis(window.getEnd()));
                    return result;
                }
                if (object instanceof GenericRowData) {
                    // Copy by position into a fresh INSERT row rather than returning the source
                    // as-is: a coincidentally equal arity does not imply matching field ordering
                    // or semantics (e.g. after schema evolution or a column reorder).
                    GenericRowData sourceRow = (GenericRowData) object;
                    int targetFieldCount = ((RowType) logicalType).getFieldCount();
                    GenericRowData result = new GenericRowData(RowKind.INSERT, targetFieldCount);
                    for (int i = 0; i < targetFieldCount; i++) {
                        result.setField(i, i < sourceRow.getArity() ? sourceRow.getField(i) : null);
                    }
                    return result;
                }
                return convertToRow(object, logicalType);
            default:
                return InternalTypeConverter.toInternal(object, logicalType);
        }
    }

