/**
     * Tests that a failure while storing a completed checkpoint in the completed checkpoint store
     * will properly fail the originating pending checkpoint and clean upt the completed checkpoint.
     */
@Test
    void testFailingCompletedCheckpointStoreAdd() throws Exception {
        JobVertexID jobVertexId = new JobVertexID();

        final ManuallyTriggeredScheduledExecutor manuallyTriggeredScheduledExecutor =
                new ManuallyTriggeredScheduledExecutor();

        ExecutionGraph testGraph =
                new CheckpointCoordinatorTestingUtils.CheckpointExecutionGraphBuilder()
                        .addJobVertex(jobVertexId)
                        .build(EXECUTOR_RESOURCE.getExecutor());

        ExecutionVertex vertex = testGraph.getJobVertex(jobVertexId).getTaskVertices()[0];

        // set up the coordinator and validate the initial state
        CheckpointCoordinator coord =
                new CheckpointCoordinatorBuilder()
                        .setCompletedCheckpointStore(
                                new FailingCompletedCheckpointStore(
                                        new Exception(
                                                "The failing completed checkpoint store failed again... :-(")))
                        .setTimer(manuallyTriggeredScheduledExecutor)
                        .build(testGraph);

        coord.triggerCheckpoint(false);

        manuallyTriggeredScheduledExecutor.triggerAll();

        assertThat(coord.getNumberOfPendingCheckpoints()).isOne();

        PendingCheckpoint pendingCheckpoint =
                coord.getPendingCheckpoints().values().iterator().next();

        assertThat(pendingCheckpoint.isDisposed()).isFalse();

        final long checkpointId = coord.getPendingCheckpoints().keySet().iterator().next();

        KeyedStateHandle managedKeyedHandle = mock(KeyedStateHandle.class);
        when(managedKeyedHandle.getStateHandleId()).thenReturn(StateHandleID.randomStateHandleId());
        KeyedStateHandle rawKeyedHandle = mock(KeyedStateHandle.class);
        when(rawKeyedHandle.getStateHandleId()).thenReturn(StateHandleID.randomStateHandleId());
        OperatorStateHandle managedOpHandle = mock(OperatorStreamStateHandle.class);
        OperatorStateHandle rawOpHandle = mock(OperatorStreamStateHandle.class);
        InputChannelStateHandle inputChannelStateHandle =
                new InputChannelStateHandle(
                        new InputChannelInfo(0, 1),
                        mock(StreamStateHandle.class),
                        Collections.singletonList(1L));
        ResultSubpartitionStateHandle resultSubpartitionStateHandle =
                new ResultSubpartitionStateHandle(
                        new ResultSubpartitionInfo(0, 1),
                        mock(StreamStateHandle.class),
                        Collections.singletonList(1L));

        final OperatorSubtaskState operatorSubtaskState =
                spy(
                        OperatorSubtaskState.builder()
                                .setManagedOperatorState(managedOpHandle)
                                .setRawOperatorState(rawOpHandle)
                                .setManagedKeyedState(managedKeyedHandle)
                                .setRawKeyedState(rawKeyedHandle)
                                .setInputChannelState(
                                        StateObjectCollection.singleton(inputChannelStateHandle))
                                .setResultSubpartitionState(
                                        StateObjectCollection.singleton(
                                                resultSubpartitionStateHandle))
                                .build());

        TaskStateSnapshot subtaskState = spy(new TaskStateSnapshot());
        subtaskState.putSubtaskStateByOperatorID(new OperatorID(), operatorSubtaskState);

        when(subtaskState.getSubtaskStateByOperatorID(
                        OperatorID.fromJobVertexID(vertex.getJobvertexId())))
                .thenReturn(operatorSubtaskState);

        AcknowledgeCheckpoint acknowledgeMessage =
                new AcknowledgeCheckpoint(
                        testGraph.getJobID(),
                        vertex.getCurrentExecutionAttempt().getAttemptId(),
                        checkpointId,
                        new CheckpointMetrics(),
                        subtaskState);

        try {
            coord.receiveAcknowledgeMessage(acknowledgeMessage, "Unknown location");
            fail(
                    "Expected a checkpoint exception because the completed checkpoint store could not "
                            + "store the completed checkpoint.");
        } catch (CheckpointException e) {
            // ignore because we expected this exception
        }

        // make sure that the pending checkpoint has been discarded after we could not complete it
        assertThat(pendingCheckpoint.isDisposed()).isTrue();

        // make sure that the subtask state has been discarded after we could not complete it.
        verify(operatorSubtaskState.getManagedOperatorState().iterator().next()).discardState();
        verify(operatorSubtaskState.getRawOperatorState().iterator().next()).discardState();
        verify(operatorSubtaskState.getManagedKeyedState().iterator().next()).discardState();
        verify(operatorSubtaskState.getRawKeyedState().iterator().next()).discardState();
        verify(
                        collectUniqueDisposableInChannelState(
                                        Stream.of(operatorSubtaskState.getInputChannelState()))
                                .iterator()
                                .next())
                .discardState();
        verify(
                        collectUniqueDisposableInChannelState(
                                        Stream.of(
                                                operatorSubtaskState.getResultSubpartitionState()))
                                .iterator()
                                .next())
                .discardState();
    }

@Test
    void testHooksAreCalledOnTrigger() throws Exception {
        final String id1 = "id1";
        final String id2 = "id2";

        final String state1 = "the-test-string-state";
        final byte[] state1serialized = new StringSerializer().serialize(state1);

        final long state2 = 987654321L;
        final byte[] state2serialized = new LongSerializer().serialize(state2);

        final MasterTriggerRestoreHook<String> statefulHook1 =
                mockGeneric(MasterTriggerRestoreHook.class);
        when(statefulHook1.getIdentifier()).thenReturn(id1);
        when(statefulHook1.createCheckpointDataSerializer()).thenReturn(new StringSerializer());
        when(statefulHook1.triggerCheckpoint(anyLong(), anyLong(), any(Executor.class)))
                .thenReturn(CompletableFuture.completedFuture(state1));

        final MasterTriggerRestoreHook<Long> statefulHook2 =
                mockGeneric(MasterTriggerRestoreHook.class);
        when(statefulHook2.getIdentifier()).thenReturn(id2);
        when(statefulHook2.createCheckpointDataSerializer()).thenReturn(new LongSerializer());
        when(statefulHook2.triggerCheckpoint(anyLong(), anyLong(), any(Executor.class)))
                .thenReturn(CompletableFuture.completedFuture(state2));

        final MasterTriggerRestoreHook<Void> statelessHook =
                mockGeneric(MasterTriggerRestoreHook.class);
        when(statelessHook.getIdentifier()).thenReturn("some-id");

        // create the checkpoint coordinator
        JobVertexID jobVertexId = new JobVertexID();
        final ExecutionGraph graph =
                new CheckpointCoordinatorTestingUtils.CheckpointExecutionGraphBuilder()
                        .addJobVertex(jobVertexId)
                        .build(EXECUTOR_RESOURCE.getExecutor());
        final ManuallyTriggeredScheduledExecutor manuallyTriggeredScheduledExecutor =
                new ManuallyTriggeredScheduledExecutor();
        final CheckpointCoordinator cc =
                instantiateCheckpointCoordinator(graph, manuallyTriggeredScheduledExecutor);

        cc.addMasterHook(statefulHook1);
        cc.addMasterHook(statelessHook);
        cc.addMasterHook(statefulHook2);

        // trigger a checkpoint
        final CompletableFuture<CompletedCheckpoint> checkpointFuture = cc.triggerCheckpoint(false);
        manuallyTriggeredScheduledExecutor.triggerAll();
        assertThat(checkpointFuture).isNotCompletedExceptionally();
        assertThat(cc.getNumberOfPendingCheckpoints()).isOne();

        verify(statefulHook1, times(1))
                .triggerCheckpoint(anyLong(), anyLong(), any(Executor.class));
        verify(statefulHook2, times(1))
                .triggerCheckpoint(anyLong(), anyLong(), any(Executor.class));
        verify(statelessHook, times(1))
                .triggerCheckpoint(anyLong(), anyLong(), any(Executor.class));

        ExecutionAttemptID attemptID =
                graph.getJobVertex(jobVertexId)
                        .getTaskVertices()[0]
                        .getCurrentExecutionAttempt()
                        .getAttemptId();

        final long checkpointId =
                cc.getPendingCheckpoints().values().iterator().next().getCheckpointID();
        cc.receiveAcknowledgeMessage(
                new AcknowledgeCheckpoint(graph.getJobID(), attemptID, checkpointId),
                "Unknown location");
        assertThat(cc.getNumberOfPendingCheckpoints()).isZero();

        assertThat(cc.getNumberOfRetainedSuccessfulCheckpoints()).isOne();
        final CompletedCheckpoint chk = cc.getCheckpointStore().getLatestCheckpoint();

        final Collection<MasterState> masterStates = chk.getMasterHookStates();
        assertThat(masterStates.size()).isEqualTo(2);

        for (MasterState ms : masterStates) {
            if (ms.name().equals(id1)) {
                assertThat(ms.bytes()).isEqualTo(state1serialized);
                assertThat(ms.version()).isEqualTo(StringSerializer.VERSION);
            } else if (ms.name().equals(id2)) {
                assertThat(ms.bytes()).isEqualTo(state2serialized);
                assertThat(ms.version()).isEqualTo(LongSerializer.VERSION);
            } else {
                fail("unrecognized state name: " + ms.name());
            }
        }
    }

